//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::closure::FindClosureOptions;
use d2_rs_text::markdown::reader::Reader;
use serde::Deserialize;
use serde_json::{Value, json};

#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Operation {
    kind: String,
    #[serde(default)]
    opener: u8,
    #[serde(default)]
    closer: u8,
    #[serde(default)]
    options: FindClosureOptions,
    #[serde(default)]
    n: isize,
    #[serde(default)]
    padding: isize,
}
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    source: String,
    peek_line: bool,
    operations: Vec<Operation>,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn evaluate(q: &Request) -> Value {
    let source: Vec<_> = (0..q.source.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&q.source[i..i + 2], 16).unwrap())
        .collect();
    let mut r = Reader::new(&source);
    let mut rows = Vec::new();
    let mut saved = r.position();
    fn snapshot(r: &mut Reader, peek_line: bool, value: Value) -> Value {
        let text = if peek_line {
            r.peek_line().0.map(|b| hex(&b.bytes()))
        } else {
            None
        };
        let (line, pos) = r.position();
        json!({"source":hex(&r.source().bytes()),"value":value,"line":line,"position":pos,"peek":r.peek(),"text":text,"offset":r.line_offset(),"preceding":r.preceding_character() as u32})
    }
    rows.push(snapshot(&mut r, q.peek_line, Value::Null));
    for op in &q.operations {
        let value = match op.kind.as_str() {
            "code-span" => {
                serde_json::to_value(d2_rs_text::markdown::inline::parse_code_span(&mut r)).unwrap()
            }
            "closure" => {
                let segments = r.find_closure(op.opener, op.closer, op.options);
                json!({"ok":segments.is_some(),"segments":segments})
            }
            "advance" => {
                r.advance(op.n);
                Value::Null
            }
            "padding" => {
                r.set_padding(op.padding);
                Value::Null
            }
            "advance-padding" => {
                r.advance_and_set_padding(op.n, op.padding);
                Value::Null
            }
            "line" => {
                r.advance_line();
                Value::Null
            }
            "eol" => {
                r.advance_to_eol();
                Value::Null
            }
            "reset" => {
                r.reset_position();
                Value::Null
            }
            "save" => {
                saved = r.position();
                Value::Null
            }
            "restore" => {
                r.set_position(saved.0, saved.1);
                Value::Null
            }
            "rune" => match r.read_rune() {
                Some((rune, size)) => json!({"rune":rune as u32,"size":size,"eof":false}),
                None => json!({"rune":0,"size":0,"eof":true}),
            },
            "spaces" | "blank" => {
                let (segment, n, ok) = if op.kind == "spaces" {
                    r.skip_spaces()
                } else {
                    r.skip_blank_lines()
                };
                json!({"segment":segment,"n":n,"ok":ok})
            }
            _ => panic!("unknown operation"),
        };
        rows.push(snapshot(&mut r, q.peek_line, value));
    }
    json!(rows)
}

#[test]
fn pinned_goldmark_reader_operations() {
    let f: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/reader.json"
    ))
    .unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (q, expected)) in f.requests.iter().zip(&f.results).enumerate() {
        let actual =
            std::panic::catch_unwind(|| evaluate(q)).unwrap_or_else(|_| json!({"panic":true}));
        assert_eq!(&actual, expected, "case {i}");
    }
}
